package p_cdbf3019a3a300007f3d219dbc66ccf3
import (
 "testing"
 rt "gopurs/output/gopurs_runtime"
)
type primeNode = Constructor_Test_Primes_Cons[int64]
var primeSink int64
func primeBaseline(n int64) int64 { return Call_Test_Primes_sumList(Call_Test_Primes_sieve(Call_Test_Primes_go__range(2,n))) }
func primeFilterForward(p rt.Value, in *primeNode) *primeNode {
 var head *primeNode
 tail := &head
 for node:=in; node!=nil; node=node.V1 {
  if rt.Apply(p,rt.Int(node.V0)).IntVal!=0 {
   next:=&primeNode{Rc:1,V0:node.V0}
   *tail=next; tail=&next.V1
  }
 }
 return head
}
func primeSieveForward(in *primeNode) *primeNode {
 if in==nil { return nil }
 p:=in.V0
 pred:=rt.Func(func(x rt.Value) rt.Value { return rt.Bool(rt.IntMod(x.IntVal,p)!=0) })
 return &primeNode{Rc:1,V0:p,V1:primeSieveForward(primeFilterForward(pred,in.V1))}
}
func primeFilterNative(p func(int64)bool, in *primeNode) *primeNode {
 var head *primeNode
 tail:=&head
 for node:=in; node!=nil; node=node.V1 {
  if p(node.V0) { next:=&primeNode{Rc:1,V0:node.V0}; *tail=next; tail=&next.V1 }
 }
 return head
}
func primeSieveNative(in *primeNode) *primeNode {
 if in==nil { return nil }
 p:=in.V0
 return &primeNode{Rc:1,V0:p,V1:primeSieveNative(primeFilterNative(func(x int64)bool{return rt.IntMod(x,p)!=0},in.V1))}
}
func primeSieveNativeTwoPass(in *primeNode) *primeNode {
 if in==nil { return nil }
 p:=in.V0
 var acc *primeNode
 for node:=in.V1;node!=nil;node=node.V1 {
  if rt.IntMod(node.V0,p)!=0 { acc=&primeNode{Rc:1,V0:node.V0,V1:acc} }
 }
 var out *primeNode
 for node:=acc;node!=nil;node=node.V1 { out=&primeNode{Rc:1,V0:node.V0,V1:out} }
 return &primeNode{Rc:1,V0:p,V1:primeSieveNativeTwoPass(out)}
}
func primeOracle(n int64) int64 {
 var total int64
 for i:=int64(2);i<=n;i++ {
  prime:=true
  for d:=int64(2);d*d<=i;d++ { if i%d==0 {prime=false;break} }
  if prime {total+=i}
 }
 return total
}
func TestPrimeOracle(t *testing.T) {
 for n:=int64(-4);n<=600;n++ {
  want:=primeOracle(n)
  for _,f:=range []func(*primeNode)*primeNode{Call_Test_Primes_sieve,primeSieveForward,primeSieveNative,primeSieveNativeTwoPass} {
   if got:=Call_Test_Primes_sumList(f(Call_Test_Primes_go__range(2,n)));got!=want {t.Fatalf("n=%d got=%d want=%d",n,got,want)}
  }
 }
}
func BenchmarkPrimeGenerated(b *testing.B) { b.ReportAllocs(); for i:=0;i<b.N;i++ { primeSink=primeBaseline(500) } }
func BenchmarkPrimeForward(b *testing.B) { b.ReportAllocs(); for i:=0;i<b.N;i++ { primeSink=Call_Test_Primes_sumList(primeSieveForward(Call_Test_Primes_go__range(2,500))) } }
func BenchmarkPrimeNative(b *testing.B) { b.ReportAllocs(); for i:=0;i<b.N;i++ { primeSink=Call_Test_Primes_sumList(primeSieveNative(Call_Test_Primes_go__range(2,500))) } }
func BenchmarkPrimeNativeTwoPass(b *testing.B) { b.ReportAllocs(); for i:=0;i<b.N;i++ { primeSink=Call_Test_Primes_sumList(primeSieveNativeTwoPass(Call_Test_Primes_go__range(2,500))) } }
